WITH valid_orders AS (SELECT * FROM orders WHERE NOT ((channel = 'store' AND status IN ('CANCELLED', 'PENDING')) OR shipping_fee <= 34)), orders_stats AS (SELECT DATE_TRUNC('MONTH', order_date) order_month, status, MIN(order_date) min_order_date, AVG(discount) avg_discount FROM valid_orders GROUP BY DATE_TRUNC('MONTH', order_date), status) SELECT order_month, status, min_order_date, avg_discount FROM orders_stats;
